-- Fabric details per category, from RCS-Fabric-Descriptions.xlsx
ALTER TABLE "categories" ADD COLUMN IF NOT EXISTS "shortLine" TEXT;
ALTER TABLE "categories" ADD COLUMN IF NOT EXISTS "material" TEXT;
ALTER TABLE "categories" ADD COLUMN IF NOT EXISTS "washCare" TEXT;

UPDATE "categories" SET "shortLine" = 'Crisp, smooth and easy to stitch', "description" = 'Poplin is a tightly woven, smooth fabric with a light, crisp feel. It holds its shape well, stitches neatly and stays comfortable through the day, which makes it a favourite for shirts, kurtis and school uniforms. It washes easily, wrinkles less than plain cotton and keeps prints and dots sharp wash after wash.', "material" = 'Cotton / poly-cotton blend', "properties" = ARRAY['Smooth','Crisp','Breathable','Lightweight']::text[], "bestFor" = ARRAY['Shirts','Kurtis','School uniforms','Tops']::text[], "washCare" = 'Wash separately the first time in cold water. Machine wash gentle or hand wash with mild detergent. Dry in shade; iron on medium heat.', "updatedAt" = NOW() WHERE lower("name") = lower('Poplin');
UPDATE "categories" SET "shortLine" = 'Glossy shine with a soft, fluid fall', "description" = 'Satin has a rich, glossy face and a smooth, cool touch that catches the light beautifully. It drapes softly and moves with the body, giving party wear and festive outfits an instantly elegant look. Ideal for gowns, blouses, sarees and evening dresses; line it for lighter shades.', "material" = 'Polyester satin', "properties" = ARRAY['Glossy','Smooth','Soft drape','Premium look']::text[], "bestFor" = ARRAY['Evening gowns','Blouses','Sarees','Party dresses']::text[], "washCare" = 'Dry clean recommended. Or gentle hand wash in cold water; do not wring or bleach. Dry in shade; iron on low heat on the reverse side.', "updatedAt" = NOW() WHERE lower("name") = lower('Satin');
UPDATE "categories" SET "shortLine" = 'Comfortable stretch for a body-fit look', "description" = 'Our stretchable fabrics move with you. They recover their shape after stretching, so body-fit dresses, tops and leggings sit neatly without feeling tight. Soft on the skin and easy to wear all day, they are a smart choice for modern, fitted outfits and active wear.', "material" = 'Polyester-spandex / lycra blend', "properties" = ARRAY['Soft','Stretchy','Smooth','Wrinkle resistant']::text[], "bestFor" = ARRAY['Body-fit dresses','Tops','Bottom wear','Active wear']::text[], "washCare" = 'Hand wash or gentle machine wash in cold water. Do not use hot water, bleach or a hot iron. Dry flat in shade to keep the stretch.', "updatedAt" = NOW() WHERE lower("name") = lower('Stretchable');
UPDATE "categories" SET "shortLine" = 'Soft, breathable everyday cotton', "description" = 'Cotton is soft, breathable and kind to the skin, the fabric you can wear every day in every season. It absorbs moisture, keeps you cool in summer and gets softer with each wash. Perfect for kurtis, kids wear, tops and relaxed casual outfits.', "material" = '100% cotton', "properties" = ARRAY['Soft','Breathable','Skin friendly','Matte']::text[], "bestFor" = ARRAY['Kurtis','Kids wear','Tops','Casual wear']::text[], "washCare" = 'Wash separately the first time in cold water; dark colours may release dye. Mild detergent, dry in shade. Iron on medium to high heat.', "updatedAt" = NOW() WHERE lower("name") = lower('Cotton');
UPDATE "categories" SET "shortLine" = 'Natural texture, made for summer', "description" = 'Linen has a natural, slightly textured weave and an easy, elegant drape. It is one of the most breathable fabrics you can wear, staying cool and fresh in heat and humidity. Its relaxed crease is part of its charm. Ideal for dresses, co-ord sets, shirts and summer ethnic wear.', "material" = 'Linen / linen-cotton blend', "properties" = ARRAY['Textured','Breathable','Light','Natural look']::text[], "bestFor" = ARRAY['Dresses','Coord sets','Shirts','Ethnic wear']::text[], "washCare" = 'Gentle wash in cold water with mild detergent. Do not tumble dry. Iron while slightly damp on medium to high heat.', "updatedAt" = NOW() WHERE lower("name") = lower('Linen');
UPDATE "categories" SET "shortLine" = 'Flowy, soft and light on the skin', "description" = 'Rayon is soft, smooth and wonderfully flowy, with a fall that makes dresses and kurtis look graceful. It feels light and cool against the skin and takes colour and prints richly. A favourite for gowns, kurtis and co-ord sets that need movement.', "material" = 'Viscose rayon', "properties" = ARRAY['Soft','Flowy','Cool','Smooth']::text[], "bestFor" = ARRAY['Dresses','Kurtis','Gowns','Coord sets']::text[], "washCare" = 'Hand wash in cold water; do not wring or twist. Wash separately the first time. Dry in shade; iron on low to medium heat. May shrink slightly: wash before stitching.', "updatedAt" = NOW() WHERE lower("name") = lower('Rayon');
UPDATE "categories" SET "shortLine" = 'Embroidered cutwork with a feminine touch', "description" = 'Hakoba is a cotton fabric decorated with fine embroidered cutwork, giving it a delicate, airy and festive look. Breathable enough for summer and pretty enough for occasions, it makes lovely kurtis, dresses and blouses. Pair it with a lining for a neat finish.', "material" = 'Cotton with schiffli embroidery', "properties" = ARRAY['Embroidered','Airy','Breathable','Delicate']::text[], "bestFor" = ARRAY['Kurtis','Dresses','Blouses','Summer wear']::text[], "washCare" = 'Gentle hand wash in cold water; do not scrub the embroidered areas. Dry in shade. Iron on the reverse side on medium heat.', "updatedAt" = NOW() WHERE lower("name") = lower('Hakoba');
UPDATE "categories" SET "shortLine" = 'Graceful fall with a fine textured surface', "description" = 'Crepe has a fine, slightly crinkled surface and a beautiful fall that flatters every silhouette. It resists wrinkles, travels well and looks polished from morning to evening. Ideal for dresses, gowns, tops and sarees.', "material" = 'Polyester crepe', "properties" = ARRAY['Textured','Flowy','Wrinkle resistant','Soft drape']::text[], "bestFor" = ARRAY['Dresses','Gowns','Tops','Sarees']::text[], "washCare" = 'Gentle hand wash in cold water or dry clean. Do not wring. Dry in shade; iron on low heat.', "updatedAt" = NOW() WHERE lower("name") = lower('Crepe');
UPDATE "categories" SET "shortLine" = 'Shimmering fabric for festive wear', "description" = 'Tissue is light, crisp and woven with a metallic shimmer that glows under festive lights. It adds instant celebration to sarees, dupattas and ethnic outfits without feeling heavy. Best stitched with a soft lining.', "material" = 'Blend with metallic yarn', "properties" = ARRAY['Shimmering','Lightweight','Crisp','Festive']::text[], "bestFor" = ARRAY['Sarees','Dupattas','Ethnic outfits','Festive dresses']::text[], "washCare" = 'Dry clean only to protect the shine. Store folded in a cotton cloth; iron on low heat on the reverse side.', "updatedAt" = NOW() WHERE lower("name") = lower('Tissue');
UPDATE "categories" SET "shortLine" = 'Sheer, light and graceful', "description" = 'Chiffon is sheer, feather-light and flows beautifully with every step. It layers well and gives sarees, dupattas and dresses a soft, elegant look. Use a lining or inner layer where you want more coverage.', "material" = 'Polyester / georgette chiffon', "properties" = ARRAY['Sheer','Light','Soft drape','Flowing']::text[], "bestFor" = ARRAY['Sarees','Dupattas','Dresses','Layered outfits']::text[], "washCare" = 'Gentle hand wash in cold water or dry clean. Do not wring or scrub. Dry in shade; iron on low heat.', "updatedAt" = NOW() WHERE lower("name") = lower('Chiffon');
UPDATE "categories" SET "shortLine" = 'Rich woven patterns with texture', "description" = 'Jacquard has its pattern woven right into the fabric, giving a rich, textured surface that looks premium from every angle. It has good body and holds structure well, ideal for jackets, blouses and festive ethnic wear.', "material" = 'Varies by design', "properties" = ARRAY['Textured','Structured','Rich','Durable']::text[], "bestFor" = ARRAY['Ethnic wear','Jackets','Blouses','Festive outfits']::text[], "washCare" = 'Dry clean recommended. Or gentle hand wash in cold water. Iron on the reverse side on low to medium heat.', "updatedAt" = NOW() WHERE lower("name") = lower('Jacquard');
UPDATE "categories" SET "shortLine" = 'Ultra-soft and airy', "description" = 'Muslin is soft, airy and light, with a gentle drape that feels lovely in warm weather. It breathes well and suits easy summer wear, kurtis, dresses and kids clothing. A comfortable fabric for everyday elegance.', "material" = 'Cotton / poly muslin', "properties" = ARRAY['Soft','Airy','Lightweight','Breathable']::text[], "bestFor" = ARRAY['Summer wear','Dresses','Kurtis','Kids wear']::text[], "washCare" = 'Gentle hand wash in cold water with mild detergent. Dry in shade. Iron on medium heat.', "updatedAt" = NOW() WHERE lower("name") = lower('Muslin');
UPDATE "categories" SET "shortLine" = 'Plain colours that go with everything', "description" = 'Our solid fabrics come in clean, plain dyed shades that are easy to style and easy to match. Use them on their own for a minimal look or pair them with prints and dupattas. Perfect for everyday kurtis, tops, dresses, shirts and bottom wear.', "material" = 'Varies by fabric', "properties" = ARRAY['Plain','Versatile','Even colour']::text[], "bestFor" = ARRAY['Kurtis','Tops','Dresses','Shirts','Bottom wear']::text[], "washCare" = 'Wash separately the first time in cold water. Mild detergent; dry in shade. Iron as per fabric type.', "updatedAt" = NOW() WHERE lower("name") = lower('Solids');

-- Check: every category below should show its short line
SELECT "name", "shortLine", "material" FROM "categories" ORDER BY "order";
